const quotePremium = (
  items: InsuredItem[],
  customer: Customer,
  isFirstContract: boolean,
): QuoteResult => ({
  premium:
    roundInMHPCOsFavor(
      applyCustomerModifiers(priceItems(items), customer, isFirstContract),
    ) + PROCESSING_FEE,
});

/**
 * Every step is a quote today, so the first step is also the first contract.
 * Once claims interleave with quotes, the Nth step stops being the Nth
 * contract and this is the line that has to learn to count quotes instead.
 */
const isFirstContractAtStep = (stepIndex: number): boolean => stepIndex === 0;

export const runScenario = (scenario: Scenario): ScenarioResults => ({
  results: scenario.steps.map((step, stepIndex) =>
    quotePremium(
      step.items ?? [],
      scenario.customer,
      isFirstContractAtStep(stepIndex),
    ),
  ),
});
